35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form: '+' followed by 8 to 15 digits")
49	    private String telephone;
50	
51	    @Column(name = "email")
52	    private String email;
53	
54	    @Column(name = "registration_date")
55	    private LocalDate registrationDate;
56	
57	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
58	    private Set<Pet> pets;
59	
60	    /**
61	     * Default the registration date to the server's current date when none was
62	     * supplied. Runs only on insert, so an explicitly provided date is kept.
63	     */
64	    @PrePersist
65	    private void defaultRegistrationDate() {
66	        if (this.registrationDate == null) {
67	            this.registrationDate = LocalDate.now();
68	        }
69	    }
70	
71	    public String getAddress() {
72	        return this.address;
73	    }
74	
75	    public void setAddress(String address) {
76	        this.address = address;
77	    }
78	
79	    public String getCity() {
