260	        return findEntityById(() -> specialtyRepository.findSpecialtiesByNameIn(names));
261	    }
262	
263	    private <T> T findEntityById(Supplier<T> supplier) {
264	        try {
265	            return supplier.get();
266	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
267	            // Just ignore not found exceptions for Jdbc/Jpa realization
268	            return null;
269	        }
270	    }
271	
272	}
